#include <vector>

using namespace std;

class Solution {
public:
    int maxDistance(vector<int>& nums1, vector<int>& nums2) {
        int res = 0, j = 0;
        for (int i = 0; i < nums1.size(); ++i) {
            j = max(j, i);
            while (j < nums2.size() && nums1[i] <= nums2[j]) ++j;
            res = max(res, j - i - 1);
        }
        return res;
    }
};
